<template><div><div class="page-head"><div><h1>Receivables</h1><p>See who owes you, how old the debt is and where to focus collections.</p></div><button class="btn btn-soft" @click="load">↻ Refresh</button></div><div class="grid grid-cols-1 gap-3 sm:grid-cols-3"><div class="card metric"><div class="metric-label">Outstanding</div><div class="metric-value mt-2">{{money(data.total)}}</div><div class="metric-trend mt-3">Open customer balances</div></div><div class="card metric"><div class="metric-label">Overdue</div><div class="metric-value mt-2">{{money(data.overdue)}}</div><div class="metric-trend mt-3 text-rose-600">Collection priority</div></div><div class="card metric"><div class="metric-label">Open invoices</div><div class="metric-value mt-2">{{format(data.count)}}</div><div class="metric-trend mt-3">Across all customers</div></div></div><div class="mt-4 grid grid-cols-1 gap-4 lg:grid-cols-5"><div v-for="a in aging" :key="a.key" class="card metric"><div class="metric-label">{{a.label}}</div><div class="metric-value mt-2 text-xl">{{money(data.aging?.[a.key])}}</div><div class="mt-3 h-2 rounded-full bg-slate-100"><div class="h-2 rounded-full bg-indigo-500" :style="{width:bar(data.aging?.[a.key])}"></div></div></div></div><div class="card mt-4 overflow-hidden"><div class="px-5 py-4"><h2 class="text-sm font-extrabold">Invoice-level collection queue</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Invoice</th><th>Client</th><th>Due</th><th>Total</th><th>Paid</th><th>Balance</th><th>Age</th><th>Action</th></tr></thead><tbody><tr v-for="i in data.invoices||[]" :key="i.id"><td>{{i.invoice_number}}</td><td>{{i.client?.name}}</td><td>{{i.due_date||'—'}}</td><td>{{money(i.total)}}</td><td>{{money(i.amount_paid)}}</td><td class="font-bold">{{money(i.balance)}}</td><td><StatusBadge :value="age(i)"/></td><td><div class="flex justify-end gap-2"><RouterLink v-if="i.client_id" :to="`/payments?client_id=${i.client_id}&invoice_id=${i.id}`" class="btn btn-primary">Collect</RouterLink><RouterLink v-if="i.client_id" :to="`/clients/${i.client_id}`" class="btn btn-soft">Client</RouterLink></div></td></tr><tr v-if="!(data.invoices||[]).length"><td colspan="8"><div class="empty">No outstanding receivables. Great work.</div></td></tr></tbody></table></div></div></div></template>
<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {api} from '../../services/api';import StatusBadge from '../../components/StatusBadge.vue';const data=ref<any>({aging:{},invoices:[]});const aging=[{key:'current',label:'Current'},{key:'1_30',label:'1–30 days'},{key:'31_60',label:'31–60 days'},{key:'61_90',label:'61–90 days'},{key:'90_plus',label:'90+ days'}];const max=computed(()=>Math.max(1,...aging.map(x=>Number(data.value.aging?.[x.key]||0))));function money(v:any){return new Intl.NumberFormat('en-TZ',{style:'currency',currency:'TZS',maximumFractionDigits:0}).format(Number(v||0))}function format(v:any){return new Intl.NumberFormat('en-TZ').format(Number(v||0))}function bar(v:any){return `${Math.max(4,Number(v||0)/max.value*100)}%`}function age(i:any){if(!i.due_date)return 'Current';const days=Math.ceil((Date.now()-new Date(i.due_date).getTime())/86400000);if(days<=0)return 'Current';if(days<=30)return '1–30 days';if(days<=60)return '31–60 days';if(days<=90)return '61–90 days';return '90+ days'}async function load(){data.value=(await api.get('/reports/receivables')).data}onMounted(load)</script>
